def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = DAILY_SALARY * 0.18
        if hp <= 3 or no_water >= 2:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    units = supply / WATER_REQ
    tight = units < 2.0
    very_tight = units < 1.5
    abundant = units >= 1.8

    opp_bids = []
    urgent_opp_bids = []
    rich_aggressive = []
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            opp_bids.append(float(pbid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_bids.append(float(pbid))
        if opp.get('budget', 0) > budget and pbid is not None and float(pbid) >= 80:
            rich_aggressive.append(float(pbid))

    highest_prev = max(opp_bids) if opp_bids else 0.0
    avg_prev = sum(opp_bids) / len(opp_bids) if opp_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else 0.0
    threat_prev = max(rich_aggressive) if rich_aggressive else highest_prev

    desperation = 0
    if hp <= 2:
        desperation += 3
    elif hp <= 4:
        desperation += 2
    elif hp <= 6:
        desperation += 1
    if no_water >= 2:
        desperation += 3
    elif no_water >= 1:
        desperation += 1

    if very_tight:
        base = 88.0
    elif tight:
        base = 62.0
    elif abundant:
        base = 28.0
    else:
        base = 42.0

    if day >= 8:
        base += 8.0
    if desperation >= 4:
        base += 28.0
    elif desperation >= 2:
        base += 14.0

    target = base

    if threat_prev > 0:
        if desperation >= 4:
            target = max(target, min(threat_prev + 2.0, 118.0))
        elif tight:
            target = max(target, min(avg_prev + 3.0, threat_prev + 1.0, 102.0))
        else:
            target = max(target, min(avg_prev * 0.72 + 2.0, 68.0))

    if urgent_prev > 0 and desperation < 4:
        target = min(target, urgent_prev - 1.5)

    if abundant and desperation == 0 and highest_prev >= 85:
        target = min(target, 24.0)

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 2.2
    elif hp > 2:
        reserve = DAILY_SALARY * 1.2
    affordable = max(0.0, budget - reserve)

    if desperation >= 4:
        affordable = budget
    elif affordable < 8.0:
        affordable = min(budget, max(8.0, budget * 0.5))

    bid = min(target, affordable)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, max(92.0, highest_prev + 1.0)))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = 75.0
    if yesterday_bids:
        base_bid = sum(yesterday_bids) / len(yesterday_bids) + 2.0

    if supply < WATER_REQ * 1.5:
        bid = base_bid * 1.2
    elif supply > WATER_REQ * 2.2:
        bid = base_bid * 0.7
    else:
        bid = base_bid

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.1)

    return min(float(my_status['budget']), float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Estimate how many water units are effectively available (integer count)
    # supply is float; ensure indices are int where needed.
    units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    # If supply is near single-unit regime, bidding contest is higher.
    single_unit_pressure = 1 if units <= 1 else 0

    # Determine base aggressiveness from yesterday's contest intensity
    # If others paid big yesterday, we slightly outbid to secure water when needed.
    need_water = (my_hp <= 3) or (my_no_water >= 1)

    # Target bid logic
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High contest: try to slightly exceed the second-highest to win without maxing out.
        target = second_prev_bid + (DAILY_SALARY * (0.06 if single_unit_pressure else 0.04))
        if need_water:
            target = max(target, highest_prev_bid * 0.98)
        else:
            target = min(target, highest_prev_bid * 0.9)
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        # Medium contest: bid around 0.65-0.8 of daily salary
        target = DAILY_SALARY * (0.7 if need_water else 0.6)
        if single_unit_pressure:
            target = max(target, highest_prev_bid * 0.9)
    else:
        # Low contest: conserve budget unless we need water.
        target = DAILY_SALARY * (0.85 if need_water else 0.5)

    # Adjust for current supply: if supply is high, we can bid less to still win.
    # supply in [15,25]; normalize.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # If supply is higher, reduce bid slightly when not in danger.
    if not need_water:
        target *= (0.92 + 0.12 * supply_norm)

    # If my hp is very low, be willing to spend aggressively.
    if my_hp <= 1:
        target = max(target, DAILY_SALARY * 0.95)

    # Final cap by budget
    bid = min(my_budget, max(0.0, float(target)))

    # Avoid bidding zero when we likely need water.
    if need_water and bid < DAILY_SALARY * 0.25:
        bid = min(my_budget, DAILY_SALARY * 0.45)

    return float(bid)
